254      private static FType narrowest(String n, List<FValue> vals,
255                                     BoundingMap<String, FType, TypeLatticeOps> abm,
256                                     List<StaticParam> rechecks, Set<String> tp_set, Environment env,
257                                     List<FType> bounds, Environment within) {
258          LinkedHashSet<FType> candidates = new LinkedHashSet<FType>();
259          for (FValue v : vals) candidates.addAll(v.type().getTransitiveExtends());
260          for (FValue v : vals) candidates.addAll(Coercions.coercionTargets(v, within));
261          if (bounds != null) candidates.addAll(bounds);
262          List<FType> admitted = new ArrayList<FType>();
263          for (FType c : candidates) {
264              if (c instanceof BottomType || c instanceof FTypeTop) continue;
265              boolean all = true;
266              for (FValue v : vals) {
267                  if (!Coercions.admits(c, v)) {
268                      all = false;
269                      break;
270                  }
271              }
272              if (!all) continue;
273              BoundingMap<String, FType, TypeLatticeOps> trial = abm.copy();
274              try {
275                  trial.joinPut(n, c);
276                  for (StaticParam tp : rechecks) {
277                      if (!NodeUtil.getName(tp).equals(n)) continue;
278                      for (Type tr : tp.getExtendsClause()) c.unify(env, tp_set, trial, tr);
279                  }
280              }
281              catch (FortressException ex) {
282                  continue;
283              }
284              catch (EmptyLatticeIntervalError ex) {
285                  continue;
286              }
287              admitted.add(c);
288          }
289          FType best = null;
290          for (FType c : admitted) {
291              boolean narrower = true;
292              for (FType d : admitted) {
293                  if (d != c && !c.subtypeOf(d) && !Coercions.convertsInto(c, d)) {
294                      narrower = false;
295                      break;
296                  }
297              }
298              if (narrower) {
299                  if (best != null && best != c) return null;
300                  best = c;
301              }
302          }
303          return best;
304      }

